// @dlc-guard:Under_Review->Approved
// @dlc-rule:BR-04
// @dlc-mask:tax_id
export function approveGrantApplication(record, actorRole) {
  if (actorRole !== 'Grant Officer' || record.state !== 'Under Review') {
    throw new DomainGuardError('Only a Grant Officer may approve an application currently Under Review.');
  }
  return { displayStatus: 'Approved', maskedTaxId: '***-**-' + String(record.taxId).slice(-4) };
}
